// lock for the duration of that disk work. No row means "gone, or changed
// meanwhile"; the caller tells the two apart.
func (q *Queries) ReplaceSiteBlob(ctx context.Context, arg ReplaceSiteBlobParams) (File, error) {
	row := q.db.QueryRowContext(ctx, replaceSiteBlob,
		arg.BlobID,
		arg.Slug,
		arg.UserID,
		arg.OldBlobID,
	)
	var i File
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.IsPublic,
		&i.AccessCode,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.SuccessCount,
		&i.FailureCount,
		&i.Tags,
		&i.ExpiresAt,
		&i.MaxViews,
		&i.ViewCount,
		&i.Kind,
		&i.CodeSuccessCount,
		&i.UserID,
		&i.ExpiredAt,
		&i.ExpiredReason,
		&i.ContentSize,
		&i.BlobID,
	)
	return i, err
}

