const softDeleteFile = `-- name: SoftDeleteFile :execrows
UPDATE files
SET deleted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP
WHERE slug = ?1 AND user_id = ?2 AND deleted_at IS NULL
`

type SoftDeleteFileParams struct {
	Slug   string `json:"slug"`
	UserID int64  `json:"user_id"`
}

// :execrows rather than :exec so the handler can tell "soft-deleted it" from
// "matched nothing" and 404 instead of reporting a success-shaped no-op.
func (q *Queries) SoftDeleteFile(ctx context.Context, arg SoftDeleteFileParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, softDeleteFile, arg.Slug, arg.UserID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const sumUserContentSize = `-- name: SumUserContentSize :one
SELECT CAST(COALESCE(SUM(content_size), 0) AS INTEGER) AS used_bytes FROM files
WHERE user_id = ?1
`

// The caller's total stored bytes, used to enforce users.quota_bytes. Trashed
// rows are included on purpose: they still occupy the database, and emptying
// the trash is a user action, so excluding them would make soft-delete an
// unlimited quota bypass.
func (q *Queries) SumUserContentSize(ctx context.Context, userID int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, sumUserContentSize, userID)
	var used_bytes int64
	err := row.Scan(&used_bytes)
	return used_bytes, err
}

const updateFile = `-- name: UpdateFile :one
UPDATE files
SET name = ?1,
    slug = ?2,
    blob_id = ?3,
    content_size = (SELECT size FROM blobs WHERE id = ?3),
    access_code = ?4,
    updated_at = CURRENT_TIMESTAMP
WHERE slug = ?5 AND user_id = ?6 AND deleted_at IS NULL
  AND kind <> 'site'
RETURNING id, slug, name, is_public, access_code, created_at, updated_at, deleted_at, success_count, failure_count, tags, expires_at, max_views, view_count, kind, code_success_count, user_id, expired_at, expired_reason, content_size, blob_id
`

type UpdateFileParams struct {
	Name       string `json:"name"`
	NewSlug    string `json:"new_slug"`
	BlobID     string `json:"blob_id"`
	AccessCode string `json:"access_code"`
	Slug       string `json:"slug"`
	UserID     int64  `json:"user_id"`
}

// The SET slug and the WHERE slug are different values; naming both explicitly
// keeps them from being mixed up (and avoids sqlc's generated `Slug_2` field).
//
// kind <> 'site' keeps document writes off site rows in SQL rather than in a
// Go check someone can forget: pointing a site at a document's blob would
// serve that document's source as a zip, and the archive would be lost.
func (q *Queries) UpdateFile(ctx context.Context, arg UpdateFileParams) (File, error) {
	row := q.db.QueryRowContext(ctx, updateFile,
		arg.Name,
		arg.NewSlug,
		arg.BlobID,
		arg.AccessCode,
		arg.Slug,
		arg.UserID,
	)
	var i File
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.IsPublic,
		&i.AccessCode,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.SuccessCount,
		&i.FailureCount,
		&i.Tags,
		&i.ExpiresAt,
		&i.MaxViews,
		&i.ViewCount,
		&i.Kind,
		&i.CodeSuccessCount,
		&i.UserID,
		&i.ExpiredAt,
		&i.ExpiredReason,
		&i.ContentSize,
		&i.BlobID,
	)
	return i, err
}

